import React from "react";
import {
  BrowserRouter,
  Routes,
  Route,
  Navigate
} from "react-router-dom";

import ProfileLayout from "./components/ProfileLayout";
import CreateProfile from "./components/userProfile";
import KycDetails from "./components/KycDetails";
import GstDetails from "./components/GstDetails";
import BankDetails from "./components/BankDetails";
import Agreement from "./components/Agreement";

function App() {
  return (
    <BrowserRouter>

      <Routes>

        <Route path="/" element={<ProfileLayout />}>

          {/* Default page */}
          <Route index element={<Navigate to="create-profile" />} />

          <Route
            path="create-profile"
            element={<CreateProfile />}
          />

          <Route
            path="kyc-details"
            element={<KycDetails />}
          />

          <Route
            path="gst-details"
            element={<GstDetails />}
          />

          <Route
            path="bank-details"
            element={<BankDetails />}
          />

          <Route
            path="agreement"
            element={<Agreement />}
          />

        </Route>

      </Routes>

    </BrowserRouter>
  );
}

export default App;
